import sys

MOD = 10**9 + 7
data = sys.stdin.read().split()
n = int(data[0])
a = [int(x) for x in data[1:1 + n]]
nz = [v for v in a if v != 0]
lo, hi = min(nz) - n, max(nz) + n

def rec(i, prev):
    if i == n:
        return 1
    if a[i] != 0:
        cands = [a[i]]
    elif i == 0:
        cands = range(lo, hi + 1)
    else:
        cands = [prev - 1, prev, prev + 1]
    total = 0
    for v in cands:
        if i == 0 or abs(v - prev) <= 1:
            total += rec(i + 1, v)
    return total

print(rec(0, 0) % MOD)

